    # Find the all-zero separator and the framed panels to its left.
    split = next(c for c in range(w) if all(row[c] == 0 for row in grid))
    left = [row[:split] for row in grid]
    bg = max({x for row in left for x in row},
             key=lambda x: sum(row.count(x) for row in left))

    # Extract the colored shapes to the right, storing each as a cropped mask.
    shapes = {}
    for color in {x for row in grid for x in row[split + 1:] if x != 0}:
        remaining = {(r, c) for r in range(h) for c in range(split + 1, w)
                     if grid[r][c] == color}
        while remaining:
            start = remaining.pop()
            component = {start}
            stack = [start]
            while stack:
                r, c = stack.pop()
                for p in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
                    if p in remaining:
                        remaining.remove(p)
                        component.add(p)
                        stack.append(p)
            r0 = min(r for r, c in component)
            r1 = max(r for r, c in component)
            c0 = min(c for r, c in component)
            c1 = max(c for r, c in component)
            shapes[color] = tuple(
                tuple((r, c) in component for c in range(c0, c1 + 1))
                for r in range(r0, r1 + 1)
            )

    boundaries = [r for r in range(h) if all(x == bg for x in left[r])]
    for top, bottom in zip(boundaries, boundaries[1:]):
        r0, r1 = top + 1, bottom
        # Exclude the panel's border columns.
        c0, c1 = 1, len(left[0]) - 1
        holes = [(r, c) for r in range(r0, r1) for c in range(c0, c1)
                 if left[r][c] == 0]
        if not holes:
